    Variables (i C1 C2 : Z).
    Hypothesis HC : 0 <= C1 < 256 /\ 0 <= C2 < 256.
    Hypothesis HI : 0 <= i <= n /\ i <= lne /\ i <= lnt.
    Hypothesis SIGN : (zstrncmp e t (Z.to_nat n) = 0 <-> C1 = C2) /\ (zstrncmp e t (Z.to_nat n) < 0 <-> C1 < C2).

